import json
txt = (data.get('raw') or '').strip()
if txt.startswith('```'):
    txt = txt.strip('`')
    txt = txt.split('json', 1)[-1].strip() if 'json' in txt[:12] else txt
obj = {}
try:
    obj = json.loads(txt)
except Exception:
    obj = {}
if not isinstance(obj, dict) or not (obj.get('access_token') or '').strip():
    # 不把原文带进报错（可能含 token）——只报格式问题
    raise SystemExit('登录输出不是预期 JSON（缺 access_token 字段）')
out = {'access_token': str(obj['access_token']).strip()}
if (obj.get('refresh_token') or '').strip():
    out['refresh_token'] = str(obj['refresh_token']).strip()
if (obj.get('token_expires_at') or '').strip():
    out['token_expires_at'] = str(obj['token_expires_at']).strip()
result = out
